"""Committed real-SMPL fixture (FR-009). Generated by the operator (tasks.md T022)."""

import time
from pathlib import Path

import pytest

from strike_a_pose.datagen.io import load_manifest, load_sample, validate_dataset

FIXTURE = Path(__file__).parent / "fixtures" / "smpl_fixture"


@pytest.mark.skipif(
    not (FIXTURE / "manifest.json").exists(),
    reason="real-SMPL fixture not generated yet (operator task T022)",
)
def test_fixture_loads_and_validates():
    t0 = time.perf_counter()
    assert validate_dataset(FIXTURE) == []
    m = load_manifest(FIXTURE)
    assert 0 < m["counts"]["samples"] <= 16
    for s in m["samples"]:
        load_sample(FIXTURE, s["id"])
    assert time.perf_counter() - t0 < 5.0  # SC-005
